<div>@if(session('success'))<div class="alert alert-success" role="status">{{ session('success') }}</div>@endif<form wire:submit="preview" class="card card-body mb-3"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="type">Jenis data</label><select id="type" class="form-select" wire:model="type"><option value="books">Buku</option><option value="students">Siswa</option><option value="teachers">Guru</option></select></div><div class="col-md-5"><label class="form-label" for="file">File CSV</label><input id="file" type="file" class="form-control" wire:model="file" accept=".csv,.txt"></div><div class="col-md-3 d-flex align-items-end gap-2"><button type="button" class="btn btn-outline-secondary" wire:click="downloadTemplate">Template</button><button class="btn btn-primary" type="submit">Preview</button></div></div></form>@if($batch)<div class="card card-body"><h2 class="h5">Preview {{ $batch->file_name }}</h2><p>Valid: {{ $batch->valid_rows }}. Tidak valid: {{ $batch->invalid_rows }}.</p><div class="table-responsive"><table class="table"><thead><tr><th>Baris</th><th>Data</th><th>Status</th></tr></thead><tbody>@foreach($batch->rows as $row)<tr><td>{{ $row->row_number }}</td><td><code>{{ json_encode($row->payload, JSON_UNESCAPED_UNICODE) }}</code></td><td>{{ $row->is_valid ? 'Valid' : json_encode($row->errors, JSON_UNESCAPED_UNICODE) }}</td></tr>@endforeach</tbody></table></div>@if($batch->valid_rows)<button class="btn btn-success" wire:click="commit">Simpan baris valid</button>@endif <button class="btn btn-outline-danger" wire:click="cancelBatch">Batalkan preview</button></div>@endif</div>
